// Pascal's triangle, rows zero through six.
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(301,225);
for (int r=0; r<=6; ++r) {
  for (int c=0; c<=r; ++c) {
    pair P = (2.4*(c - r/2.0), 1.6*(6-r));
    dot(P, black+1.5pt);
    label("$"+string(r)+","+string(c)+"$", P, NE);
  }
}
label("each entry is the sum of the two above it", (3.0,-0.7), S);

// Choosing two letters from the first group, one from the second, and two
// from the third.
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(321,111);
draw((-1.2,0)--(1.4,0)--(1.4,0.9)--(-1.2,0.9)--cycle);
draw((0.5,0)--(3.1,0)--(3.1,0.9)--(0.5,0.9)--cycle);
draw((2.2,0)--(4.8,0)--(4.8,0.9)--(2.2,0.9)--cycle);
dot((-0.8,0.45), black+3pt);
dot((-0.1,0.45), black+3pt);
dot((0.5,0.45), black+2pt);
dot((1.0,0.45), black+2pt);
dot((0.8,0.45), black+3pt);
dot((1.6,0.45), black+2pt);
dot((2.3,0.45), black+2pt);
dot((2.9,0.45), black+2pt);
dot((2.6,0.45), black+3pt);
dot((3.4,0.45), black+3pt);
dot((4.0,0.45), black+2pt);
dot((4.5,0.45), black+2pt);
label("$a$", (0.1,-0.3), N);
label("$b$", (1.8,-0.3), N);
label("$c$", (3.5,-0.3), N);
label("two, one, two", (1.8,-0.9), S);
